const response = $input.first()?.json ?? {};
const elements = response.elements ?? response.body?.elements ?? [];

const source = $('Build Search Query').first().json;
const requestedLimit = Math.max(
  1,
  Math.min(100, Number(source.requestedLimit) || 25)
);

const seen = new Set();
const prospects = [];

for (const element of elements) {
  const tags = element.tags ?? {};
  const name = String(tags.name ?? '').trim();

  // Unnamed map elements are not useful company prospects.
  if (!name) continue;

  const key = `${element.type}/${element.id}`;
  if (seen.has(key)) continue;
  seen.add(key);

  const lat = element.lat ?? element.center?.lat ?? null;
  const lon = element.lon ?? element.center?.lon ?? null;

  const street = [
    tags['addr:housenumber'],
    tags['addr:street']
  ].filter(Boolean).join(' ');

  const address = [
    street,
    tags['addr:suburb'],
    tags['addr:city'] ?? tags['addr:town'],
    tags['addr:postcode'],
    tags['addr:country']
  ].filter(Boolean).join(', ');

  prospects.push({
    json: {
      search_id : source.search_id,
      execution_id : source.execution_id,
      source: 'OpenStreetMap',
      osm_id: key,
      name,
      category: source.mappedCategory,
      industry_requested: source.industry,
      location_requested: source.location,
      ideal_customer_type : source.ideal_customer_type,
      address: address || null,
      website: tags.website ?? tags['contact:website'] ?? tags.url ?? null,
      phone: tags.phone ?? tags['contact:phone'] ?? null,
      email: tags.email ?? tags['contact:email'] ?? null,
      latitude: lat,
      longitude: lon,
      osm_url: `https://www.openstreetmap.org/${element.type}/${element.id}`,
      discovery_status: 'discovered'
    }
  });

  if (prospects.length >= requestedLimit) break;
}

return prospects;

const input = $input.first().json
const industry = String(input.industry || "").trim().toLowerCase()
const location = String(input.location || "").split(",")[0].toLowerCase()

if (!industry || !location){
  throw new Error ('industry and location are required')
}
const maxResult = Math.max(1,
      Math.min(100, Number(input.max_result) || 25))

return [{
  json: {
    ...input,
    industry,
    location,
    max_result: maxResult
  }
}];

const response = $input.first().json;
const businesses = response.businesses;
const searchInput = $('Prepare BizData Search').first().json;

if (!Array.isArray(businesses)) {
  throw new Error('Expected a businesses array in the API response.');
}

return businesses.map(business => ({
  json: {
    search_id :searchInput.search_id,
    execution_id :searchInput.execution_id,
    source: 'bizdata',
    osm_id: business.osm_id || null,
    name: business.name || '',
    category: business.category || '',
    industry_requested: searchInput.industry,
    location_requested: searchInput.location,
    ideal_customer_type: searchInput.ideal_customer_type,
    address: business.address || '',
    website: business.website || '',
    phone: business.phone || '',
    email: business.email || '',
    latitude: business.lat ?? null,
    longitude: business.lon ?? null,
    opening_hours: business.opening_hours || '',
    osm_url: business.osm_url || null,
    discovery_status: 'discovered'
  }
}));

const items = $input.all();

const uniqueProspects = new Map();

function normalizeDomain(website) {
  if (!website) return null;

  try {
    const url = new URL(
      website.includes('://') ? website : `https://${website}`
    );

    return url.hostname
      .toLowerCase()
      .replace(/^www\./, '')
      .replace(/\.$/, '');
  } catch {
    return null;
  }
}

function normalizeText(value) {
  return String(value || '')
    .toLowerCase()
    .replace(/[^\p{L}\p{N}]+/gu, ' ')
    .trim()
    .replace(/\s+/g, ' ');
}

for (const item of items) {
  const prospect = item.json;

  const domain = normalizeDomain(prospect.website);

  const name = normalizeText(prospect.name);

  const address = normalizeText(
    prospect.address || prospect.location_requested
  );

  // Use both keys so a record with a website
  // can also match one without a website.
  const keys = [];

  if (domain) {
    keys.push(`domain:${domain}`);
  }

  if (name && address) {
    keys.push(`name_location:${name}|${address}`);
  }

  if (!keys.length) {
    keys.push(`unmatched:${uniqueProspects.size}`);
  }

  let existing = null;

  for (const key of keys) {
    if (uniqueProspects.has(key)) {
      existing = uniqueProspects.get(key);
      break;
    }
  }

  if (!existing) {
    const record = {
      ...prospect,
      sources: [prospect.source]
    };

    for (const key of keys) {
      uniqueProspects.set(key, record);
    }

    continue;
  }

  // Preserve information from both sources.
  for (const [field, value] of Object.entries(prospect)) {
    if (
      (existing[field] === null ||
        existing[field] === undefined ||
        existing[field] === '') &&
      value !== null &&
      value !== undefined &&
      value !== ''
    ) {
      existing[field] = value;
    }
  }

  if (
    prospect.source &&
    !existing.sources.includes(prospect.source)
  ) {
    existing.sources.push(prospect.source);
  }

  // Register additional matching keys.
  for (const key of keys) {
    uniqueProspects.set(key, existing);
  }
}

return [...new Set(uniqueProspects.values())].map(prospect => ({
  json: prospect
}));

