const prospect_data = $input.first().json
const search_id = [
  Date.now().toString(36),
  Math.random().toString(36).slice(2, 10)
].join('-');
return  [{
  json: {
  ...prospect_data,
    search_id,
    execution_id: $execution.id,
    status: 'running'
  }
}];

const prospect_data = $input.all().map(item => item.json);

return prospect_data.map(item => ({
  json: {
    ...item,
    processing_stage: 'website_fetch',
    review_reason: 'website_unreachable',
    error_type: 'website_fetch_error',
    error_message: item.error?.message || 'Website could not be reached'
  }
}));

const input = $('Start Search').first().json;

const industry = String(input.industry || '').trim().toLowerCase();
const location = String(input.location || '').split(',')[0].trim();

if (!industry || !location) {
  throw new Error('Industry and location are required.');
}

// Supported OpenStreetMap categories
const categories = {
  dentist: ['amenity', 'dentist'],
  'dental clinic': ['amenity', 'dentist'],
  restaurant: ['amenity', 'restaurant'],
  cafe: ['amenity', 'cafe'],
  hotel: ['tourism', 'hotel'],
  pharmacy: ['amenity', 'pharmacy'],
  supermarket: ['shop', 'supermarket'],
  'real estate': ['office', 'estate_agent'],
  lawyer: ['office', 'lawyer'],
  'law firm': ['office', 'lawyer'],
  'marketing agency': ['office', 'advertising_agency'],
  'software company': ['office', 'it'],
  'it company': ['office', 'it'],
  'web design agency': ['office', 'it'],
};

const match = Object.entries(categories)
  .find(([name]) => industry.includes(name));

if (!match) {
  throw new Error(
    `No OpenStreetMap category mapping for "${industry}". ` +
    'Add a matching category before searching.'
  );
}

const [tagKey, tagValue] = match[1];


const maxResults = Math.max(
  1,
  Math.min(100, Number(input.max_result) || 25)
);


const geo = $('Find Location').first().json;

const lat = Number(geo.lat);
const lon = Number(geo.lon);

if (!Number.isFinite(lat) || !Number.isFinite(lon)) {
  throw new Error('Valid latitude and longitude are required.');
}

const query = `
[out:json][timeout:25];
nwr["${tagKey}"="${tagValue}"](around:10000,${lat},${lon});
out center tags ${maxResults};
`;

return [{
  json: {
    ...input,
    overpassQuery: query,
    mappedCategory: `${tagKey}=${tagValue}`,
    requestedLimit: maxResults
  }
}];

const prospects = $input.all().map(prospect => prospect.json)
return prospects.map(prospect => {
  let data_quality
  const hasWebsite = Boolean(prospect.website)
  const hasPhone = Boolean(prospect.phone)
  const hasAddress = Boolean(prospect.address)
  if (hasWebsite){
    data_quality = "sufficient_data"}
  else if (hasPhone || hasAddress){
    data_quality = "limited_data"}
  else{
    data_quality = "insufficient_data"
  }
  return {
    json:{
      ...prospect,
      data_quality
    }
  }
});

const prospect_data = $input.all().map(item => item.json);

return prospect_data.map(item => ({
  json: {
    ...item,
    processing_stage: 'website_fetch',
    review_reason: 'missing_website',
    error_type: 'missing_website',
    error_message: 'Website is not available; website fetching was not attempted'
  }
}));

return $input.all().map((item, i) => {
  const text = item.json.content?.parts?.[0]?.text;

  if (!text) {
    throw new Error('Gemini response text not found');
  }

  const cleanText = text
    .replace(/^```json\s*/i, '')
    .replace(/\s*```$/, '')
    .trim();

  const qualification = JSON.parse(cleanText);

  const prospect = $('Read Website Content').itemMatching(i).json;

  return {
    json: {
      ...prospect,
      ...qualification
    },
    pairedItem: { item: i }
  };
});

return $input.all().map((item, i) => {
  const prospect = $('Parse AI Results').itemMatching(i).json;

  return {
    json: prospect,
    pairedItem: {
      item: i
    }
  };
});

