function decodeHtml(text) {
  return text
    .replace(/&amp;/gi, '&')
    .replace(/&quot;/gi, '"')
    .replace(/&#39;|&apos;/gi, "'")
    .replace(/&lt;/gi, '<')
    .replace(/&gt;/gi, '>')
    .replace(/&nbsp;|&#160;/gi, ' ')
    .trim();
}

function extractMetaDescription(html) {
  const tags = html.match(/<meta\b[^>]*>/gi) || [];

  const tag = tags.find(t =>
    /\bname\s*=\s*["']description["']/i.test(t)
  );

  return tag?.match(/\bcontent\s*=\s*["']([^"']*)["']/i)?.[1] ?? '';
}

return $input.all().map((item, index) => {

  const html = String(item.json.data ?? '');

  // Retrieve the matching original prospect
  const original = $('Ready for AI?').itemMatching(index).json;

  const website_title = decodeHtml(
    html.match(/<title[^>]*>([\s\S]*?)<\/title>/i)?.[1] ?? ''
  );

  const website_description = decodeHtml(
    extractMetaDescription(html)
  );

  const website_evidence = decodeHtml(
    html
      .replace(/<script\b[^>]*>[\s\S]*?<\/script>/gi, ' ')
      .replace(/<style\b[^>]*>[\s\S]*?<\/style>/gi, ' ')
      .replace(/<noscript\b[^>]*>[\s\S]*?<\/noscript>/gi, ' ')
      .replace(/<!--[\s\S]*?-->/g, ' ')
      .replace(/<[^>]+>/g, ' ')
      .replace(/\s+/g, ' ')
  );

  const uniqueEvidence = [...new Set(
    website_evidence
      .split(/(?<=[.!?])\s+/)
      .map(text => text.trim())
      .filter(text => text.length > 25)
  )].join(' ').slice(0, 1500);

  return {
    json: {
      ...original,
      website_title,
      website_description: website_description.slice(0, 300),
      website_evidence: uniqueEvidence,
      website_fetch_status: html.length > 0 ? 'success' : 'empty'
    }
  };
});

const prospect_data = $input.all().map(item => item.json);

return prospect_data.map(item => ({
  json: {
    ...item,
   processing_stage: 'ai_qualification',
   review_reason: 'ai_qualification_failed',
   error_type: 'ai_error',
   error_message: String(item.error)
  }
}));

const prospect_data = $("Parse AI Results").all().map(item => item.json)
const responses = $input.all().map(item => item.json)
return responses.map((response, index)=> ({
    json:{
      ...response,
      search_id: prospect_data[index].search_id
    }
  }));
